import{_ as t,c as n,o as r,a2 as a}from"./chunks/framework.PGES7OoM.js";const s="/assets/curvy-withdrawal-flow.BSN7YXWd.png",c=JSON.parse(`{"title":"Unshielding funds privately","description":"","frontmatter":{"rawMarkdown":"# Unshielding funds privately\\n\\nAfter some time and many privately and securely received payments from his clients, Bob is ready to sell a portion of his crypto on a centralized exchange (CEX) to buy a house.\\n\\nIn the previous scenarios, we covered the first two of the three actions of **Aggregator.sol**: shielding and aggregation.\\n\\nNow we will need the third one: unshielding.\\n\\n![Unshielding funds privately](./curvy-withdrawal-flow.png)\\n\\n## Steps explained in detail\\n\\n### 🟢 Bob\\n\\n**1.** Bob's **Curvy SDK** syncs its local Merkle tree from the **Indexer** and scans the notes to match the ones in his ownership, decrypting their balances and exact tokens.\\n\\n**2.** The **Local ZK prover**, running entirely on Bob's device, generates the withdrawal proof — aggregating multiple notes into a single one if needed — with the CEX's address as the withdrawal destination, and sends it to the **Relayer**.\\n\\n### ⚫ Curvy\\n\\n**3.** The **Relayer** relays the withdrawal proof to **Aggregator.sol**, submitting the withdrawal request on-chain. After verifying the proof, **Aggregator.sol** automatically transfers the funds from itself to the Centralized Exchange's address.\\n\\n> [!IMPORTANT]\\n> From the perspective of an on-chain observer, funds have simply moved from **Aggregator.sol** to the CEX's address. The information about the previous owner of the funds, and the notes themselves that were aggregated into a single note for unshielding, is completely hidden.\\n","rawMarkdownPath":"/_raw/for-the-curious/walkthroughs/unshielding-funds-privately.md","rawMarkdownTitle":"Unshielding funds privately","rawMarkdownUrl":"https://docs.curvy.box/_raw/for-the-curious/walkthroughs/unshielding-funds-privately.md"},"headers":[],"relativePath":"for-the-curious/walkthroughs/unshielding-funds-privately.md","filePath":"for-the-curious/walkthroughs/unshielding-funds-privately.md","lastUpdated":1784117553000}`),o={name:"for-the-curious/walkthroughs/unshielding-funds-privately.md"};function i(l,e,d,h,g,u){return r(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="unshielding-funds-privately" tabindex="-1">Unshielding funds privately <a class="header-anchor" href="#unshielding-funds-privately" aria-label="Permalink to &quot;Unshielding funds privately&quot;">​</a></h1><p>After some time and many privately and securely received payments from his clients, Bob is ready to sell a portion of his crypto on a centralized exchange (CEX) to buy a house.</p><p>In the previous scenarios, we covered the first two of the three actions of <strong>Aggregator.sol</strong>: shielding and aggregation.</p><p>Now we will need the third one: unshielding.</p><p><img src="'+s+'" alt="Unshielding funds privately"></p><h2 id="steps-explained-in-detail" tabindex="-1">Steps explained in detail <a class="header-anchor" href="#steps-explained-in-detail" aria-label="Permalink to &quot;Steps explained in detail&quot;">​</a></h2><h3 id="🟢-bob" tabindex="-1">🟢 Bob <a class="header-anchor" href="#🟢-bob" aria-label="Permalink to &quot;🟢 Bob&quot;">​</a></h3><p><strong>1.</strong> Bob&#39;s <strong>Curvy SDK</strong> syncs its local Merkle tree from the <strong>Indexer</strong> and scans the notes to match the ones in his ownership, decrypting their balances and exact tokens.</p><p><strong>2.</strong> The <strong>Local ZK prover</strong>, running entirely on Bob&#39;s device, generates the withdrawal proof — aggregating multiple notes into a single one if needed — with the CEX&#39;s address as the withdrawal destination, and sends it to the <strong>Relayer</strong>.</p><h3 id="⚫-curvy" tabindex="-1">⚫ Curvy <a class="header-anchor" href="#⚫-curvy" aria-label="Permalink to &quot;⚫ Curvy&quot;">​</a></h3><p><strong>3.</strong> The <strong>Relayer</strong> relays the withdrawal proof to <strong>Aggregator.sol</strong>, submitting the withdrawal request on-chain. After verifying the proof, <strong>Aggregator.sol</strong> automatically transfers the funds from itself to the Centralized Exchange&#39;s address.</p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>From the perspective of an on-chain observer, funds have simply moved from <strong>Aggregator.sol</strong> to the CEX&#39;s address. The information about the previous owner of the funds, and the notes themselves that were aggregated into a single note for unshielding, is completely hidden.</p></div>',12)])])}const f=t(o,[["render",i]]);export{c as __pageData,f as default};
